import { readFile, readdir } from 'node:fs/promises'
import { builtinModules } from 'node:module'
import { resolve, relative, dirname, isAbsolute, sep } from 'node:path'
import { fileURLToPath } from 'node:url'
const builtins = new Set(builtinModules.flatMap((name) => [name, 'node:' + name]))
const policies = {
  'packages/runtime-contracts/src': new Set(),
  'packages/metamodel-domain/src': new Set(),
  'packages/metamodel-compiler/src': new Set(['@frade/metamodel-domain']),
  'packages/runtime-node/src': new Set([
    '@frade/runtime-contracts',
    '@frade/draw/document',
    'saxes',
    '@frade/adapter-yaml',
    '@frade/adapter-sberea-yaml',
    '@frade/repository-domain',
    '@frade/repository-ports',
    '@frade/metamodel-config',
    '@frade/metamodel-domain',
    '@frade/repository-api',
    '@frade/repository-api/workbench',
    '@frade/repository-application',
    '@frade/local-index',
  ]),
  'packages/runtime-electron/src': new Set(['@frade/runtime-contracts']),
  'apps/desktop/src/renderer': new Set([
    'react',
    'react-dom/client',
    '@frade/draw',
    '@frade/draw/styles.css',
    '@frade/ui-workspace',
    '@frade/ui-workspace/styles.css',
    '@frade/ui-workspace/design/theme',
    '@frade/ui-workspace/design/tokens.css',
    '@frade/ui-workspace/design/theme/theme-consumers.css',
    '@frade/repository-api/workbench',
    '@frade/runtime-contracts',
  ]),
}
function allowed(file, specifier, scope, imports) {
  if (specifier.startsWith('.')) {
    const target = relative(resolve(scope), resolve(dirname(file), specifier))
    return target !== '..' && !target.startsWith('..' + sep) && !isAbsolute(target)
  }
  if (scope.replaceAll('\\', '/').endsWith('runtime-node/src') && builtins.has(specifier))
    return true
  return imports.has(specifier)
}
async function sources(root) {
  const entries = await readdir(root, { withFileTypes: true })
  const nested = await Promise.all(
    entries.map((e) =>
      e.isDirectory()
        ? sources(resolve(root, e.name))
        : /\.(ts|tsx)$/.test(e.name)
          ? [resolve(root, e.name)]
          : [],
    ),
  )
  return nested.flat()
}
export function inspectRuntimeSource(file, content, scope, imports) {
  const violations = []
  const pattern = /(?:\bfrom\s+|\bimport(?:\s+|\s*\(\s*)|\brequire\s*\(\s*)['"]([^'"]+)['"]/g
  for (const match of content.matchAll(pattern))
    if (!allowed(file, match[1], scope, new Set(imports)))
      violations.push(file + ': forbidden import ' + match[1])
  return violations
}
export async function checkRuntimeBoundaries(root) {
  const violations = []
  for (const [scope, imports] of Object.entries(policies)) {
    const absolute = resolve(root, scope)
    for (const file of await sources(absolute))
      violations.push(
        ...(scope === 'packages/metamodel-domain/src'
          ? inspectMetamodelSource(file, await readFile(file, 'utf8'), absolute)
          : scope === 'packages/metamodel-compiler/src'
            ? inspectCompilerSource(file, await readFile(file, 'utf8'), absolute)
            : inspectRuntimeSource(file, await readFile(file, 'utf8'), absolute, imports)),
      )
  }
  const manifest = JSON.parse(
    await readFile(resolve(root, 'packages/metamodel-domain/package.json'), 'utf8'),
  )
  violations.push(...metamodelManifestViolations(manifest))
  const compilerManifest = JSON.parse(
    await readFile(resolve(root, 'packages/metamodel-compiler/package.json'), 'utf8'),
  )
  violations.push(...compilerManifestViolations(compilerManifest))
  return violations
}
export function inspectMetamodelSource(file, content, scope) {
  const violations = inspectRuntimeSource(file, content, scope, [])
  if (/\b(?:eval|Function|require)\s*\(|\bimport\s*\(/.test(content))
    violations.push(file + ': dynamic execution or loading is forbidden')
  return violations
}
export function metamodelManifestViolations(manifest) {
  return ['dependencies', 'optionalDependencies', 'peerDependencies'].flatMap((field) =>
    Object.keys(manifest[field] ?? {}).map(
      (name) => 'packages/metamodel-domain/package.json: forbidden ' + field + ' ' + name,
    ),
  )
}
export function inspectCompilerSource(file, content, scope) {
  const violations = inspectRuntimeSource(file, content, scope, ['@frade/metamodel-domain'])
  if (/\b(?:eval|Function|require)\s*\(|\bimport\s*\(/.test(content))
    violations.push(file + ': dynamic execution or loading is forbidden')
  return violations
}
export function compilerManifestViolations(manifest) {
  return ['dependencies', 'optionalDependencies', 'peerDependencies'].flatMap((field) =>
    Object.keys(manifest[field] ?? {})
      .filter((name) => field !== 'dependencies' || name !== '@frade/metamodel-domain')
      .map((name) => 'packages/metamodel-compiler/package.json: forbidden ' + field + ' ' + name),
  )
}
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const errors = await checkRuntimeBoundaries(
    resolve(dirname(fileURLToPath(import.meta.url)), '..'),
  )
  if (errors.length) {
    console.error(errors.join('\n'))
    process.exitCode = 1
  } else console.log('Runtime architecture boundaries: PASS')
}

import { parseDocument, type DiagramDocument } from './schema'

export type DrawingPage = {
  id: string
  name: string
  graph: DiagramDocument['graph']
  viewport?: DiagramDocument['viewport']
}
export type MultipageDocument = {
  format: 'frade-draw'
  version: 2
  metadata: DiagramDocument['metadata']
  pages: DrawingPage[]
}
export type DrawingDocument = DiagramDocument | MultipageDocument
export type DrawingState = {
  version: 1 | 2
  metadata: DiagramDocument['metadata']
  pages: DrawingPage[]
  activeId: string
}

function record(value: unknown): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value))
    throw Error('Invalid drawing structure')
  return value as Record<string, unknown>
}
function name(value: unknown, message: string): string {
  if (typeof value !== 'string' || !value.trim()) throw Error(message)
  return value
}

/** Validate every graph before any editor/session replacement. The v1 API stays unchanged. */
export function parseDrawingDocument(value: unknown): DrawingDocument {
  const input = record(value)
  if (input.version !== 2) return parseDocument(value)
  if (input.format !== 'frade-draw') throw Error('Unsupported document format')
  const metadata = parseDocument({
    format: 'frade-draw',
    version: 1,
    metadata: input.metadata,
    graph: { nodes: [], edges: [] },
  }).metadata
  if (!Array.isArray(input.pages) || !input.pages.length) throw Error('Drawing needs a page')
  const ids = new Set<string>()
  const pages = input.pages.map((value) => {
    const page = record(value),
      id = name(page.id, 'Invalid page ID')
    if (ids.has(id)) throw Error('Duplicate page ID')
    ids.add(id)
    const parsed = parseDocument({
      format: 'frade-draw',
      version: 1,
      metadata,
      graph: page.graph,
      ...(page.viewport === undefined ? {} : { viewport: page.viewport }),
    })
    return {
      id,
      name: name(page.name, 'Invalid page name'),
      graph: parsed.graph,
      ...(parsed.viewport === undefined ? {} : { viewport: parsed.viewport }),
    }
  })
  return { format: 'frade-draw', version: 2, metadata, pages }
}
export const serializeDrawingDocument = (value: DrawingDocument) =>
  JSON.stringify(parseDrawingDocument(value), null, 2)
export const deserializeDrawingDocument = (json: string) => parseDrawingDocument(JSON.parse(json))

export function pageState(value: unknown, firstName = 'Страница-1'): DrawingState {
  const document = parseDrawingDocument(value)
  const pages =
    document.version === 2
      ? document.pages
      : [
          {
            id: document.metadata.id + '/page-1',
            name: firstName,
            graph: document.graph,
            ...(document.viewport === undefined ? {} : { viewport: document.viewport }),
          },
        ]
  return {
    version: document.version,
    metadata: document.metadata,
    pages,
    activeId: pages[0].id,
  }
}
export function drawingDocument(state: DrawingState): DrawingDocument {
  if (state.version === 2)
    return {
      format: 'frade-draw',
      version: 2,
      metadata: state.metadata,
      pages: state.pages,
    }
  const page = state.pages[0]
  return {
    format: 'frade-draw',
    version: 1,
    metadata: state.metadata,
    graph: page.graph,
    ...(page.viewport === undefined ? {} : { viewport: page.viewport }),
  }
}
export function semanticDrawing(value: DrawingDocument) {
  const parsed = parseDrawingDocument(value)
  if (parsed.version === 1) {
    return {
      format: parsed.format,
      version: parsed.version,
      metadata: parsed.metadata,
      graph: parsed.graph,
    }
  }
  return {
    ...parsed,
    pages: parsed.pages.map(({ id, name, graph }) => ({ id, name, graph })),
  }
}
/** Semantic dirty key: object formatting/order and navigation are not diagram edits. */
export function drawingContentKey(json: string): string {
  return JSON.stringify(semanticDrawing(deserializeDrawingDocument(json)), (_key, value) =>
    value && typeof value === 'object' && !Array.isArray(value)
      ? Object.fromEntries(
          Object.keys(value)
            .sort()
            .map((key) => [key, value[key]]),
        )
      : value,
  )
}
function pageIndex(state: DrawingState, id: string) {
  const index = state.pages.findIndex((page) => page.id === id)
  if (index < 0) throw Error('Page no longer exists')
  return index
}
function newPage(state: DrawingState, page: DrawingPage) {
  if (state.pages.some((current) => current.id === page.id)) throw Error('Duplicate page ID')
  const parsed = parseDrawingDocument({
    format: 'frade-draw',
    version: 2,
    metadata: state.metadata,
    pages: [page],
  }) as MultipageDocument
