  'stroke',
  'strokeWidth',
  'strokeDasharray',
  'opacity',
  'fillOpacity',
  'strokeOpacity',
  'rx',
  'ry',
  'fontSize',
  'fontFamily',
  'fontWeight',
  'fontStyle',
  'textAnchor',
